def now(): return datetime.now(timezone.utc).isoformat()
def shab(b:bytes): return hashlib.sha256(b).hexdigest()
def shaf(p:Path): return shab(p.read_bytes())
def git(*a): return subprocess.check_output(['git',*a],cwd=ROOT,text=True).strip()
def fsyncdir(p:Path):
 fd=os.open(p,os.O_RDONLY|os.O_DIRECTORY)
 try: os.fsync(fd)
 finally: os.close(fd)
def put(name:str,obj:Any):
 EVIDENCE.mkdir(parents=True,exist_ok=True); data=(json.dumps(obj,indent=2,sort_keys=True)+'\n').encode(); fd,tmp=tempfile.mkstemp(prefix='.'+name+'.',dir=EVIDENCE)
 try:
  with os.fdopen(fd,'wb') as f: f.write(data); f.flush(); os.fsync(f.fileno())
  dst=EVIDENCE/name; os.replace(tmp,dst); fsyncdir(EVIDENCE)
  if dst.read_bytes()!=data: raise RuntimeError('readback:'+name)
  return shab(data)
 finally:
  if os.path.exists(tmp): os.unlink(tmp)
