 rel={'L1':'A precedes B only if A preserves all currently supported individual obligations and B makes at least one unschedulable, with no converse loss','L2':'strict inclusion of fixed finite supported continuation sets only; no count/cardinality/optimization','L3':'A-now vs B-now then one specified recovery only; no open-ended sequence search','prohibited':['EDF/LLF direct selection','minimum laxity','horizon min/max/sum','schedule/future counts','owner priority','weights','utility/reward','planner rollout']}
 cases=[{'id':i,'semantic':s,'supported_facts':support,'unknown_facts':not support,'expected_relation_possible':relation,'authority_layer':'ordinary unless explicitly hard/active boundary'} for i,s,support,relation in CASES]
 d=put('AS003L_REGULATORY_OBLIGATION_ONTOLOGY_LOCK.json',meta()|{'phase':'A_ONTOLOGY_LOCK','ontology':ontology,'relation_families':rel,'source_fingerprints':src(),'lock_rule':'semantic families/cases cannot change after this artifact'})
