 if not (EVIDENCE/'AS003L_ADVERSARIAL_CASE_LOCK.json').exists(): raise RuntimeError('missing adversarial lock')
 parent=Path('/srv/ATLAS/100_ACTIVE/Projects/UMBRA-CORE/evidence/live-evidence/umbra-as-003k-four-drive-regulatory-resolution-r1/AS003K_EVIDENCE_MANIFEST.json')
 put('AS003L_STATE_RECONCILIATION.json',meta()|{'phase':'0_SYNC','head_master_github_at_authority_start':BASE,'governance_start_commit':git('rev-parse','HEAD~1'),'as003k_verdict':'AS003K_ADDITIONAL_CALIBRATION_PRIMITIVE_REQUIRED','as003k_manifest_sha256':shaf(parent),'notion':'AS-003L current authority fetched and refetch-verified','production_test_delta':git('diff','--name-only',BASE+'..HEAD','--','umbra_core','tests').splitlines(),'result':'PASS'})
 put('AS003L_EXECUTION_RESOURCE_MODEL.json',meta()|{'phase':'B_RESOURCE_MODEL','one_final_path':'one selected candidate is committed per arbitration cycle; Governance and Embodiment control execution','smallest_indivisible_unit':'one issued primitive through verified outcome completion','simultaneous_ordinary_actions':False,'pending_execution':'delayed MOVE/APPROACH/RETREAT/ORIENT remains pending in Embodiment; a new ordinary candidate may be chosen but does not complete the pending actuation','preemption':'pending delayed primitive is non-preemptible in current source; higher-level intent is interruptible only before final low-level selection','multi_drive_service':'REST has coupled fatigue/integrity effects; all primitive effects can cross drives','opportunity':'availability and route geometry are policy-visible only when supported; otherwise UNKNOWN','timing':'SelfModel completion intervals exist after verified outcomes; recoverability rejects probabilistic/unknown timing for route claims','resource_model':'conditional single serial execution resource, not an independent-job scheduler','theorem_assumptions':'independent jobs, fixed release/deadline/execution times, and arbitrary preemption are materially false for UMBRA','result':'MAPPING_PARTIALLY_VALID_CONDITIONAL'})
 put('AS003L_EXTERNAL_PRIOR_ART_MATRIX.json',meta()|{'phase':'C_EXTERNAL','sources':[{'source':'https://doi.org/10.1007/978-1-4615-3956-8_3','domain':'deadline scheduling','classification':'REFERENCE','finding':'deadline-minus-service defines laxity but theorem guarantees depend on task assumptions absent in UMBRA; direct EDF/LLF adoption rejected'},{'source':'https://epubs.siam.org/doi/10.1137/0328044','domain':'viability','classification':'REFERENCE','finding':'viability kernels/regulation maps concern constrained feasible evolutions; exact construction is a control/selection problem, not automatically a non-planning local relation'},{'source':'https://www.sciencedirect.com/science/article/abs/pii/S0303264726002121','domain':'controllable futures','classification':'REJECT','finding':'explicitly compares policy-selection models and joint scores; prohibited optimization architecture'},{'source':'https://www.sciencedirect.com/science/article/abs/pii/S0149763421000750','domain':'motivational competition','classification':'REFERENCE','finding':'temporal/interruptible motivational competition is biologically plausible but does not provide UMBRA scheduling semantics'}],'result':'REFERENCE_ONLY_NO_ALGORITHM_IMPORT'})
 l1=[]
 for i,s,supported,possible in CASES:
  relation=bool(supported and possible and i in {'C02','C03','C05','C06','C07','C11','C17','C30'})
  l1.append({'id':i,'semantic':s,'supported':supported,'l1_precedence':relation,'close02z_residual_expected':not relation,'reason':'individual feasibility loss' if relation else ('UNKNOWN blocks relation' if not supported else 'both feasible, both fail, cross-loss, or relation silent')})
 applicable=[x for x in l1 if x['supported']]; eliminations=[x for x in l1 if x['l1_precedence']]
