 put('AS003L_BOUNDEDNESS_AND_PLANNING_BOUNDARY.json',meta()|{'phase':'F_BOUNDARY','drive_ceiling':4,'L1':'one immediate candidate plus independently supported one-obligation recovery check; bounded and read-only but insufficient for joint obligations','L2_upper_bound_if_idealized':'4! = 24 orderings for four single-service obligations before route alternatives, delayed commitments, effect branches, releases, and opportunity changes','L2_actual_requirement':'to establish Feasible(B) subset Feasible(A), source must choose/project multiple future corrective actions and their order under coupled effects and changing opportunity/timing support','classification':'PLANNING_BOUNDARY','reason':'the useful joint relation is an explicit bounded future-action sequence search. Finite cardinality does not erase its planning character.','result':'L2_NOT_ADOPTABLE'})
