 put('AS003L_HYPOTHESIS_CHALLENGE.json',meta()|{'phase':'K_CHALLENGE','answers':{'obligations':'conditionally analogous only when deadline, opportunity, capability and duration are supported','serial_resource':'one final primitive path exists, but delayed/nonpreemptible commitment weakens textbook analogy','viable_loss_deadline':'valid conditional completion deadline, not direct drive value','service_demand':'valid only as supported opportunity-specific route plus completion evidence','coupling':'invalidates independent-job assumptions and makes joint feasibility order-sensitive','opportunity_uncertainty':'UNKNOWN must block relation; present source lacks universal timing support','bounded_feasibility':'enumerating future corrective order is planning despite four-drive bound','organism_competition':'L1 captures real deferment danger; L2 becomes a plan constructor','hidden_priority':'avoided in L1; reappears if orders are selected/optimized','within_viable_conflict':'partially resolved only where one immediate action destroys supported feasibility','residual_conflicts':'legitimate if both continuations remain feasible','resource_use':'does not justify implementation because full useful relation crosses planning boundary'},'result':'PLANNING_BOUNDARY_REQUIRED'})
